dtsPropsFor.ConnectionCard:
/** A union discriminated on format_version; the card branches on it in five places.
   * v1 has NO observation and passage-only anchors, and renders read-only with a legacy
   * notice. Both carry ConnectionRecordMetadata. `kind` is a CLOSED vocabulary —
   * KIND_LABELS[connection.kind] is the first expression the component evaluates, so an
   * unknown kind is an immediate crash, not a fallback. */
  connection:
    | { id: string; format_version: 1; kind: "link:parallel" | "link:contrast" | "link:echo" | "mirror" | "series" | "hinge"; label: string; anchors: Array<{ book: string; chapter: number; verse_start: number; verse_end: number }>; activeEventId: string; createdAt: string; updatedAt: string }
    | { id: string; format_version: 2; kind: "link:parallel" | "link:contrast" | "link:echo" | "mirror" | "series" | "hinge"; label: string; observation: string; anchors: Array<{ book: string; chapter: number; verse_start: number; verse_end: number } & { exact: { format_version: 1; layer: "backbone-token:v1"; occurrences: Array<{ verse: number; position: number }> } }>; activeEventId: string; createdAt: string; updatedAt: string };
  /** Package-local paint evidence. `quote` is where every visible phrase comes from —
   * without fragments each row reads "Exact wording unavailable in this translation". */
  paintAnchors: readonly ({ book: string; chapter: number; verse_start: number; verse_end: number } & { fragments: readonly { verse: number; char_start: number; char_end: number; quote: string }[] })[];
  bookNames: Record<string, string[]>;
  book: string;
  chapter: number;
  packageId: string;
  otherHeldCount: number;
  onDismiss: (restoreFocus?: boolean) => void;
  onClose: (restoreFocus?: boolean) => void;
  onJump: (anchor: { book: string; chapter: number; verse_start: number; verse_end: number }) => void;
  onNote: (connection: unknown) => void;
  onExtend: (connection: unknown) => void;
  /** Resolves to a BARE STRING union — not an object. Returning { status } reads as
   * "not complete" at runtime. In a DESIGN these may resolve immediately with "complete". */
  onUpdate: (connection: unknown, commandId: string, expectedBaseEventId: string) => Promise<"complete" | "committed-pending" | "conflict" | "failed">;
  onDelete: (connection: unknown, commandId: string, expectedBaseEventId: string) => Promise<"complete" | "committed-pending" | "conflict" | "failed">;
  onRefresh: () => void;
  /** ConnectionCardRecovery — there is no `message` field. */
  recovery?: { kind: "update" | "delete"; state: "committed-pending" | "unconfirmed"; command: unknown; visibleConnection: unknown } | null;
  onRecoveryChange: (recovery: unknown | null) => void;
  onMutationStateChange?: (state: "idle" | "in-flight" | "recovery") => void;
  onExitControllerChange?: (controller: unknown | null) => void;

dtsPropsFor.RenderingOrbitView:
/** NOTE: hubLabel, hubMeta and hubDir are IDENTITY-ONLY — the 70px hub went out with
   * the donut, so hubLabel survives only as a useEffect dep and hubDir:"rtl" does nothing
   * visible. `surface`, `dir` and `lang` are likewise not read by the current body. */
  model?: {
    hubLabel: string;
    hubMeta?: string;
    total: number;
    /** When empty, the parent owns the kicker (mode pills). */
    kicker: string;
    segments: Array<{ label: string; count: number; share: number; isCurrent?: boolean }>;
    ariaLabel: string;
    hubDir?: "ltr" | "rtl";
    /** Set false for a non-frequency orbit that must hide counts. */
    countMeta?: boolean;
    /** What the unranked rest are, as a plural noun — C·4 §3·6 writes "6 more renderings", a phrase, not "+6". */
    remainderNoun?: string;
  };
  orbit?: { segments: Array<{ label: string; count: number; share: number; isCurrent?: boolean }> };
  surface?: string;
  dir?: "ltr" | "rtl";
  lang?: string;
  /** Two-step: first activation focuses the row; a second on the focused row fires this. Hover previews without navigating. */
  onSelectSegment?: (index: number, segment: { label: string; count: number; share: number; isCurrent?: boolean }) => void;
